 for(const sign of[-1,1]){box([.65,5.2,d],[sign*4.675,0,-d/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.9],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,d],[0,-2.275,-d/2],'floor');box([8.7,4.55,.65],[0,.325,-d+.325],'deep rear wall');box([4.8,.45,2.3],[0,2.375,-4.6],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.7],[(i-1.5)*2,.2,-3.7],'contact '+(i+1),gold));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-6],'solder tail '+(i+1),gold);}
