 const barrel=ring(g,2.78,2.05,7,[0,0,-7],gold,'C6L '+id+' annular RP-SMA outer barrel');const lip=ring(g,2.78,2.05,.4,[0,0,-.4],gold,'C6L '+id+' open RP-SMA mating lip');class Thread extends THREE.Curve{getPoint(t,v=new THREE.Vector3()){const a=t*tau*7.2;return v.set(Math.cos(a)*2.94,Math.sin(a)*2.94,-5.6+t*5.0);}}const thread=mesh(g,new THREE.TubeGeometry(new Thread(),512,.14,8,false),gold,[0,0,0],'C6L '+id+' continuous external helical thread');const dielectric=ring(g,2.04,.47,2.5,[0,0,-3.1],white,'C6L '+id+' centre dielectric');const pin=mesh(g,new THREE.CylinderGeometry(.36,.36,2.5,32).rotateX(Math.PI/2),gold,[0,0,-1.6],'C6L '+id+' actual reverse-polarity centre pin');const tip=mesh(g,new THREE.SphereGeometry(.36,24,12),gold,[0,0,-.4],'C6L '+id+' rounded exposed centre pin tip');
